            'workshop,likelihood,net,plan'],
    ],
    ['code' => 'risk-limit-breach', 'prof' => 'risk-manager', 'type' => 'situational', 'lvl' => [3, 5], 'diff' => 4, 'sec' => 210, 'skills' => ['decision_making', 'communication'],
        'fr' => ['Une limite de risque est dépassée par une équipe commerciale très rentable. Que faites-vous ?', 'Indépendance, escalade, analyse, plan de retour sous limite.',
