    ['code' => 'pm-fr-late', 'prof' => 'project-manager-fr', 'type' => 'behavioral', 'lvl' => [2, 5], 'diff' => 3, 'sec' => 210, 'skills' => ['project_methodology', 'decision_making', 'communication'],
        'fr' => ['Racontez un projet en retard que vous avez redressé.', 'STAR : causes, plan de redressement, communication, résultat.',
