    // Project Manager (international, agile)
    ['code' => 'pm-agile-hybrid', 'prof' => 'project-manager', 'type' => 'technical', 'lvl' => [2, 5], 'diff' => 3, 'sec' => 210, 'skills' => ['project_methodology', 'decision_making'],
        'fr' => ['Comment choisissez-vous entre une approche agile et une approche prédictive ?', 'Critères de choix et éventuelle approche hybride.',
            ['Stabilité des besoins|besoin,stable,incertain,evolutif,exigences', 'Contraintes du contexte|contrat,reglementaire,forfait,date fixe,budget', 'Implication du client|client,product owner,disponibilite,feedback', 'Approche hybride|hybride,combiner,jalons,sprints,adapter'],
            ['Choisir l\'agilité par effet de mode', 'Appliquer une méthode de façon dogmatique'],
            'Je regarde d\'abord le niveau d\'incertitude sur les besoins : s\'ils vont évoluer, l\'agilité permet d\'ajuster par itérations. Je tiens compte des contraintes : contrat au forfait, exigences réglementaires, date fixe. La disponibilité d\'un product owner est déterminante. Souvent, j\'adopte une approche hybride avec des jalons contractuels et des sprints pour le développement.',
            'incertitude,contrainte,product owner,hybride'],
        'en' => ['How do you choose between an agile and a predictive approach?', 'Selection criteria and a possible hybrid approach.',
            ['Stability of requirements|requirement,stable,uncertain,evolving,changing', 'Context constraints|contract,regulat,fixed price,fixed date,budget', 'Client involvement|client,product owner,availability,feedback', 'Hybrid approach|hybrid,combine,milestones,sprints,adapt'],
            ['Choosing agile because it is trendy', 'Applying a method dogmatically'],
            'I first look at uncertainty in requirements: if they will change, agile lets us adjust through iterations. I consider constraints: fixed price contract, regulatory requirements, fixed dates. Having an available product owner is decisive. Often I use a hybrid approach with contractual milestones and sprints for delivery.',
            'uncertainty,constraint,product owner,hybrid'],
    ],
    ['code' => 'pm-distributed', 'prof' => 'project-manager', 'type' => 'situational', 'lvl' => [2, 5], 'diff' => 3, 'sec' => 210, 'skills' => ['multicultural', 'communication', 'project_methodology'],
        'fr' => ['Comment coordonnez-vous une équipe répartie sur trois fuseaux horaires ?', 'Rituels, communication asynchrone, outils, cohésion.',
